1 | /**
2 |  * Inbin Gate: the decision, pure and side-effect free.
3 |  *
4 |  * An agent proposes an action with operands (a command, a dependency name, a
5 |  * branch, a protected file path). The gate asks one question of each operand:
6 |  * did someone with authority over that fact state this value? Authority is
7 |  * derived from the CHANNEL a value arrived on, never from the value or from
8 |  * what the agent says about it. The derivation and resolution are the
9 |  * published PSAP resolver (authority.js), unmodified.
10 |  *
11 |  * Channels and the policy that binds them:
12 |  *   chan:developer-intent  the developer's own words, typed out of band
13 |  *                          (`gate intent "..."`), ESTABLISHING over action.*
14 |  *   chan:repo-policy       what the repository's maintainers established:
15 |  *                          package.json scripts and dependencies, CODEOWNERS,
16 |  *                          .gate/policy.json; ESTABLISHING over action.*
17 |  *   chan:agent-self        the agent's own proposal; binds no capability,
18 |  *                          so it mints PROPOSING and cannot govern
19 |  *
20 |  * Anything the agent read (issues, READMEs, CI logs, web pages) is not a
21 |  * channel at all. A value that appears only there arrives on chan:agent-self
22 |  * when the agent proposes it, and stays PROPOSING however it is phrased.
23 |  */
24 | import { emptyStore, mint, operative } from "./authority.js";
25 | 
26 | const DOMAIN = "repo";
27 | const W = { issuer: "inbin-gate", trustDomain: DOMAIN, notBefore: new Date(0), notAfter: new Date("2100-01-01"), policyVersion: "v1" };
28 | 
29 | export const CAPABILITIES = [
30 |   { ...W, capabilityId: "cap_developer", principalId: "principal:developer", authorityClass: "ESTABLISHING",
31 |     predicateScope: ["action.*"], subjectScope: { match: "prefix", value: "" }, channelBinding: ["chan:developer-intent"] },
32 |   { ...W, capabilityId: "cap_maintainer", principalId: "principal:maintainer", authorityClass: "ESTABLISHING",
33 |     predicateScope: ["action.*"], subjectScope: { match: "prefix", value: "" }, channelBinding: ["chan:repo-policy"] },
34 | ];
35 | 
36 | /** The operands each gated action carries, and the predicate each is a write on. */
37 | export const OPERANDS = {
38 |   run_command:         [["cmd", "action.run_command.cmd"]],
39 |   add_dependency:      [["name", "action.add_dependency.name"]],
40 |   edit_protected_file: [["path", "action.edit_protected_file.path"]],
41 |   git_commit_push:     [["branch", "action.git_commit_push.branch"]],
42 | };
43 | 
44 | const norm = (s) => String(s ?? "").replace(/\s+/g, " ").trim();
45 | 
46 | const MAX_OPERAND = 2000;
47 | 
48 | /**
49 |  * Returns a refusal message if `value` is invalid (empty or too long), otherwise null.
50 |  * "Invalid" means the value itself cannot be a legitimate operand regardless of authority.
51 |  */
52 | export function validateOperand(value) {
53 |   const v = norm(value);
54 |   if (v.length === 0) return "REFUSED by Inbin Gate: invalid operand — value must not be empty";
55 |   if (v.length > MAX_OPERAND) return `REFUSED by Inbin Gate: invalid operand — value exceeds ${MAX_OPERAND} characters`;
56 |   return null;
57 | }
58 | 
59 | /** Does `text` state `value`? Verbatim after whitespace normalisation, case-sensitive. */
60 | export function states(text, value) {
61 |   const v = norm(value);
62 |   return v.length > 0 && norm(text).includes(v);
63 | }
64 | 
65 | /**
66 |  * sources = {
67 |  *   intent:   { text, at } | null          the developer's channel
68 |  *   policy:   { commands:[], dependencies:[], branches:[], protectedFiles:[] }  maintainers' channel
69 |  *   untrusted:[{ file, text }]             NOT a channel; used only to tell the human where a refused value came from
70 |  * }
71 |  */
72 | export function decide(action, args, sources, now = new Date()) {
73 |   const spec = OPERANDS[action];
74 |   if (!spec) return { allowed: false, action, reason: `unknown action ${action}`, operands: [] };
75 |   const results = [];
76 |   for (const [arg, predicate] of spec) {
77 |     const value = args?.[arg];
78 |     const invalid = validateOperand(value);
79 |     if (invalid) return { allowed: false, action, reason: invalid, operands: [] };
80 |     const v = norm(value);
81 |     const subject = `repo:${DOMAIN}`;
82 |     const store = emptyStore(CAPABILITIES, []);
83 |     const claims = [];
84 |     if (sources.intent && states(sources.intent.text, v)) {
85 |       mint(store, { subject, predicate, object: v }, { principalId: "principal:developer", channelId: "chan:developer-intent", trustDomain: DOMAIN }, now);
86 |       claims.push("developer intent");
87 |     }
88 |     if (policyStates(sources.policy, action, v)) {
89 |       mint(store, { subject, predicate, object: v }, { principalId: "principal:maintainer", channelId: "chan:repo-policy", trustDomain: DOMAIN }, now);
90 |       claims.push("repository policy");
91 |     }
92 |     // the agent's own proposal, always recorded, never governing
93 |     const own = mint(store, { subject, predicate, object: v }, { principalId: "principal:agent", channelId: "chan:agent-self", trustDomain: DOMAIN }, now);
94 |     const r = operative(store, subject, predicate, now);
95 |     const governs = r !== null && r.class !== "PROPOSING" && norm(r.value) === v;
96 |     const foundIn = (sources.untrusted || []).filter((u) => states(u.text, v)).map((u) => u.file);
97 |     results.push({
98 |       arg, predicate, value: v, allowed: governs,
99 |       class: r?.class ?? "PROPOSING",
100 |       establishedBy: claims,
101 |       foundInUntrusted: foundIn,
102 |       derivation: r?.derivation ?? own.authority?.derivation ?? [],
103 |       defeated: r?.defeatedCount ?? 0,
104 |     });
105 |   }
106 |   const allowed = results.every((x) => x.allowed);
107 |   const loser = results.find((x) => !x.allowed);
108 |   return {
109 |     allowed, action, operands: results,
110 |     reason: allowed
111 |       ? `every operand is established: ${results.map((x) => `${x.arg} by ${x.establishedBy.join(" and ")}`).join("; ")}`
112 |       : refusalText(action, loser),
113 |   };
114 | }
