116 | function policyStates(policy, action, v) {
117 |   if (!policy) return false;
118 |   const lists = {
119 |     run_command: policy.commands || [],
120 |     add_dependency: policy.dependencies || [],
121 |     git_commit_push: policy.branches || [],
122 |     edit_protected_file: policy.editableProtectedFiles || [],
123 |   }[action] || [];
124 |   return lists.some((x) => norm(x) === v);
125 | }
